[CmdletBinding()]
param([int]$DurationMinutes=0,[int]$IntervalSeconds=10,[int]$FailureThreshold=3)
throw 'MANUAL_START_ONLY: this automatic restart watchdog is disabled. Use run-lan-availability-smoke.ps1 for observation only.'
$ErrorActionPreference='SilentlyContinue';$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$runtimeDir=Join-Path $root 'data\runtime';New-Item -ItemType Directory -Path $runtimeDir -Force|Out-Null;$lockPath=Join-Path $runtimeDir 'lan-supervisor.pid';
if(Test-Path -LiteralPath $lockPath){$oldPid=[int](Get-Content -LiteralPath $lockPath -Raw);if(Get-Process -Id $oldPid -ErrorAction SilentlyContinue){throw "LAN_SUPERVISOR_ALREADY_RUNNING PID=$oldPid"}}
Set-Content -LiteralPath $lockPath -Value $PID -Encoding utf8
$statePath=Join-Path $runtimeDir 'lan-supervisor-state.json';$previous=try{Get-Content -LiteralPath $statePath -Raw|ConvertFrom-Json}catch{$null};$previousRestartCount=if($previous){[int]$previous.restartCount}else{0};$state=[pscustomobject]@{status='RUNNING';startedAt=[DateTimeOffset]::UtcNow.ToString('o');restartCount=0;lastRestartAt=$null;lastRestartReason=$null;lastError=$null;previousRestartCount=$previousRestartCount}
function Probe([string]$Url){$sw=[Diagnostics.Stopwatch]::StartNew();$wire=curl.exe --connect-timeout 2 --max-time 5 -s -o NUL -w '%{http_code}|%{time_total}' $Url 2>$null;$sw.Stop();$code=0;$seconds=$sw.Elapsed.TotalSeconds;if($wire -match '^([0-9]+)\|([0-9.]+)$'){$code=[int]$Matches[1];$seconds=[double]$Matches[2]};[pscustomobject]@{url=$Url;status=if($code -eq 200){'UP'}elseif($code -eq 503){'STARTING'}else{'DOWN'};responsive=$code -in 200,503;ready=$code -eq 200;httpCode=$code;latencyMs=[math]::Round($seconds*1000,2)}}
function LanIps(){@(Get-NetIPAddress -AddressFamily IPv4 -Type Unicast|Where-Object {$_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254.*' -and $_.AddressState -eq 'Preferred'}|Select-Object -ExpandProperty IPAddress)}
function SaveState($value){$value|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $statePath -Encoding utf8}
function Emit([string]$Type,$Payload){try{Invoke-RestMethod -Uri 'http://127.0.0.1:8080/api/v3/ops/lan/event' -Method Post -ContentType 'application/json' -Body (@{type=$Type;payload=$Payload}|ConvertTo-Json -Depth 8) -TimeoutSec 3|Out-Null}catch{}}
try{$deadline=if($DurationMinutes -gt 0){(Get-Date).AddMinutes($DurationMinutes)}else{$null};$localFailures=0;while(!$deadline -or (Get-Date)-lt $deadline){$ips=LanIps;$lanIp=($ips|Where-Object {$_ -like '192.168.*'}|Select-Object -First 1);if(!$lanIp){$lanIp=$ips|Select-Object -First 1};$listener=Get-NetTCPConnection -LocalPort 8080 -State Listen|Select-Object -First 1;$owner=$null;if($listener){$owner=Get-CimInstance Win32_Process -Filter "ProcessId=$($listener.OwningProcess)"};$local=Probe 'http://127.0.0.1:8080/health';$lan=if($lanIp){Probe "http://${lanIp}:8080/health"}else{[pscustomobject]@{status='NO_LAN_IP';responsive=$false;ready=$false;httpCode=0;latencyMs=$null}};$profile=Get-NetConnectionProfile|Where-Object {$_.IPv4Connectivity -ne 'NoTraffic'}|Select-Object -First 1;$rule=Get-NetFirewallRule -DisplayName 'ZDJ-MITS Engine 8080';$remote=if($rule){(($rule|Get-NetFirewallAddressFilter).RemoteAddress -join ',')}else{'NOT_FOUND'};$engineAlive=[bool]($owner -and $owner.CommandLine -match '(^|[\s/])dist[\/]main\.js([\s]|$)');if($engineAlive -and $local.responsive){$localFailures=0}else{$localFailures++};$current=[ordered]@{timestamp=[DateTimeOffset]::UtcNow.ToString('o');pid=if($listener){$listener.OwningProcess}else{$null};engineAlive=$engineAlive;listener=[bool]$listener;listenerAddress=if($listener){$listener.LocalAddress}else{$null};local=$local;lan=$lan;lanIps=$ips;networkProfile=[string]$profile.NetworkCategory;networkInterface=$profile.InterfaceAlias;firewallRuleState=[ordered]@{present=[bool]$rule;enabled=$rule.Enabled;profile=[string]$rule.Profile;remoteAddress=$remote};supervisor=[ordered]@{status='RUNNING';pid=$PID;localFailureStreak=$localFailures;failureThreshold=$FailureThreshold;restartCount=$state.restartCount}};$current|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $runtimeDir 'lan-supervisor-state.json') -Encoding utf8;if(!$listener){Emit 'LAN_LISTENER_DOWN' @{pid=$null;reason='NO_8080_LISTENER'}}elseif(!$engineAlive){Emit 'LAN_PORT_OWNERSHIP_CHANGED' @{pid=$listener.OwningProcess;command=$owner.CommandLine}}elseif(!$local.responsive){Emit 'LAN_LOOPBACK_HTTP_DOWN' @{pid=$listener.OwningProcess;httpCode=$local.httpCode;latencyMs=$local.latencyMs}}if($localFailures -ge $FailureThreshold){$state.restartCount=[int]$state.restartCount+1;$state.lastRestartAt=$current.timestamp;$state.lastRestartReason=if(!$engineAlive){'ENGINE_PROCESS_DEAD'}else{'LOCAL_HEALTH_CONSECUTIVE_FAILURE'};$state.status='RESTARTING';SaveState $state;Emit 'SUPERVISOR_RESTART' @{reason=$state.lastRestartReason;restartCount=$state.restartCount;pid=$listener.OwningProcess};& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'scripts\start-zdj-lan.ps1') -StartReason 'SUPERVISOR_RESTART'|Out-File -FilePath (Join-Path $runtimeDir 'supervisor-start.log') -Append -Encoding utf8;$localFailures=0;$state.status='RUNNING';SaveState $state};Start-Sleep -Seconds ([math]::Max(5,$IntervalSeconds))}}finally{$state.status='STOPPED';$state.stoppedAt=[DateTimeOffset]::UtcNow.ToString('o');SaveState $state;if(Test-Path -LiteralPath $lockPath){[System.IO.File]::Delete($lockPath)}}
